import json, re, sys
from pathlib import Path

RULES = json.loads("[{\"t\": \"lines\", \"min\": 7}]")
TARGET = "reply.md"

BULLET = re.compile(r"^\s*(?:[-*•–]|\d+[.)])\s+\S")
ABBR = re.compile(r"\b(?:Mr|Mrs|Ms|Dr|Prof|St|vs|etc|No|approx|Inc|Ltd|Jr|Sr)\.|\b(?:e\.g|i\.e)\.|\d\.\d")


def words_all(text):
    return text.split()


def words_alnum(text):
    return [t for t in text.split() if re.search(r"[A-Za-z0-9]", t)]


def sentences(text):
    t = re.sub(r"(?m)^\s*(?:[-*•]|\d+[.)])\s+", "", text)
    t = ABBR.sub(lambda m: m.group(0).replace(".", ""), t)
    parts = re.split(r"(?<=[.!?])[\"')\]]*\s+", t.strip())
    return [p for p in parts if re.search(r"[A-Za-z0-9]", p)]


def match_any(pats, text):
    for p in pats:
        if p.startswith("re:"):
            if re.search(p[3:], text, re.I | re.M):
                return True
        elif p.lower() in text.lower():
            return True
    return False


def has_word(w, text):
    return re.search(r"(?<![A-Za-z0-9])" + re.escape(w) + r"(?![A-Za-z0-9])", text, re.I) is not None


def body_of(text, r):
    pre = r.get("skip_prefix")
    if pre:
        lines = text.splitlines()
        while lines and re.match(pre, lines[0]):
            lines.pop(0)
        return "\n".join(lines)
    return text


def run_checks(rules, text, extra_fn=None):
    fails = []
    for r in rules:
        t = r["t"]
        b = body_of(text, r)
        if t == "max_words":
            n = len(words_alnum(b))
            if n > r["n"]:
                fails.append(f"too long: {n} words, the limit is {r['n']}")
        elif t == "min_words":
            n = len(words_all(b))
            if n < r["n"]:
                fails.append(f"too short: {n} words, at least {r['n']} wanted")
        elif t == "max_chars":
            n = len(b.strip())
            if n > r["n"]:
                fails.append(f"too long: {n} characters, the limit is {r['n']}")
        elif t == "min_chars":
            n = len(b.strip())
            if n < r["n"]:
                fails.append(f"too short: {n} characters, at least {r['n']} wanted")
        elif t == "bullets":
            n = sum(1 for ln in b.splitlines() if BULLET.match(ln))
            if "min" in r and n < r["min"]:
                fails.append(f"{n} list items, at least {r['min']} wanted")
            if "max" in r and n > r["max"]:
                fails.append(f"{n} list items, at most {r['max']} allowed")
        elif t == "lines":
            n = len([ln for ln in b.splitlines() if ln.strip()])
            if "min" in r and n < r["min"]:
                fails.append(f"{n} non-blank lines, at least {r['min']} wanted")
            if "max" in r and n > r["max"]:
                fails.append(f"{n} non-blank lines, at most {r['max']} allowed")
        elif t == "paragraphs":
            blocks = [x for x in re.split(r"\n\s*\n", b.strip()) if x.strip()]
            n = len(blocks)
            if "min" in r and n < r["min"]:
                fails.append(f"{n} paragraphs, at least {r['min']} wanted")
            if "max" in r and n > r["max"]:
                fails.append(f"{n} paragraphs, at most {r['max']} allowed")
        elif t == "sentences":
            n = len(sentences(b))
            if "min" in r and n < r["min"]:
                fails.append(f"{n} sentences, at least {r['min']} wanted")
            if "max" in r and n > r["max"]:
                fails.append(f"{n} sentences, at most {r['max']} allowed")
        elif t == "include":
            if not match_any(r["any"], b):
                fails.append(f"missing: {r.get('label') or r['any'][0]}")
        elif t == "exclude":
            for w in r["words"]:
                if w.startswith("re:"):
                    if re.search(w[3:], b, re.I | re.M):
                        fails.append(f"must not contain /{w[3:]}/")
                elif has_word(w, b):
                    fails.append(f"must not contain {w!r}")
        elif t == "first_line":
            lines = [ln for ln in text.splitlines() if ln.strip()]
            if not lines or not re.search(r["re"], lines[0].strip()):
                fails.append(f"first line must match /{r['re']}/ (label: {r.get('label', '')})")
        elif t == "last_line":
            lines = [ln for ln in text.splitlines() if ln.strip()]
            if not lines or not re.search(r["re"], lines[-1].strip()):
                fails.append(f"last line must match /{r['re']}/ (label: {r.get('label', '')})")
        elif t == "every_line":
            for ln in b.splitlines():
                if not ln.strip():
                    continue
                if r.get("skip") and re.search(r["skip"], ln):
                    continue
                if not re.search(r["re"], ln):
                    fails.append(f"line does not match /{r['re']}/: {ln[:60]!r}")
                    break
        elif t == "no_line":
            for ln in b.splitlines():
                if re.search(r["re"], ln):
                    fails.append(f"forbidden line pattern /{r['re']}/: {ln[:60]!r}")
                    break
        elif t == "max_line_chars":
            for ln in b.splitlines():
                if len(ln) > r["n"]:
                    fails.append(f"a line is {len(ln)} characters, the limit is {r['n']}: {ln[:40]!r}")
                    break
        elif t == "headings":
            hs = [re.sub(r"^#+\s*", "", ln).strip() for ln in b.splitlines() if re.match(r"^#{1,6}\s+\S", ln)]
            want = r["list"]
            if r.get("ci", True):
                hs_c = [h.lower() for h in hs]
                want_c = [w.lower() for w in want]
            else:
                hs_c, want_c = hs, want
            if r.get("exact", True):
                if hs_c != want_c:
                    fails.append(f"headings should be {want} in order, found {hs}")
            else:
                it = iter(hs_c)
                if not all(w in it for w in want_c):
                    fails.append(f"headings should include {want} in order, found {hs}")
        elif t == "numbers_subset":
            allowed = set(str(x) for x in r["allowed"])
            for m in re.finditer(r"(?<![A-Za-z0-9.])\d[\d,]*(?:\.\d+)?%?", b):
                tok = m.group(0).rstrip(",").replace(",", "")
                if tok not in allowed and tok.rstrip("%") not in allowed:
                    fails.append(f"number {tok!r} does not appear in the source material")
                    break
        elif t == "json_file":
            pass
        else:
            fails.append(f"unknown rule {t}")
    if extra_fn:
        try:
            fails.extend(extra_fn(text))
        except Exception as e:
            fails.append(f"extra check raised {type(e).__name__}: {e}")
    return fails



import re
START, END = 630, 750
MINS = {'Customer feedback': 25, 'Office move': 20, 'Incident retro': 15, 'Vendor contracts': 15}
CAP = None
BEFORE = None
BRKW = None


def _t(s):
    h, m = s.split(":")
    return int(h) * 60 + int(m)


def extra(text):
    fails = []
    rows = []
    for ln in text.splitlines():
        if not ln.strip():
            continue
        m = re.match(r"^\s*[-*]?\s*(\d\d:\d\d)\s*[-\u2013]\s*(\d\d:\d\d)\s+(.+?)\s*$", ln)
        if not m:
            fails.append("line not in the form HH:MM-HH:MM Topic: " + ln[:50])
            continue
        rows.append((_t(m.group(1)), _t(m.group(2)), m.group(3)))
    if not rows:
        return fails
    if rows[0][0] != START:
        fails.append("first item must start at the meeting start")
    if rows[-1][1] != END:
        fails.append("last item must end at the meeting end")
    for a, b in zip(rows, rows[1:]):
        if a[1] != b[0]:
            fails.append("gap or overlap between " + a[2] + " and " + b[2])
    for s, e, name in rows:
        if e <= s or (e - s) % 5:
            fails.append("duration not a positive multiple of 5: " + name)
    names = [r[2].lower() for r in rows]
    if names[0] != "welcome" or rows[0][1] - rows[0][0] != 5:
        fails.append("first item must be a 5-minute Welcome")
    if names[-1] not in ("wrap-up", "wrap up", "wrapup") or rows[-1][1] - rows[-1][0] != 5:
        fails.append("last item must be a 5-minute Wrap-up")
    brk = [r for r in rows if r[2].lower() == "break"]
    if len(brk) != 1 or brk[0][1] - brk[0][0] != 10 or brk is rows[0] or brk[0] is rows[0] or brk[0] is rows[-1]:
        fails.append("need exactly one 10-minute Break that is neither first nor last")
    for t, mn in MINS.items():
        hit = [r for r in rows if r[2].lower() == t.lower()]
        if len(hit) != 1:
            fails.append("topic missing or repeated: " + t)
        else:
            du = hit[0][1] - hit[0][0]
            if du < mn:
                fails.append(t + " is shorter than its minimum")
            if CAP and du > CAP:
                fails.append(t + " is longer than the cap")
    others = [r for r in rows if r[2].lower() not in [x.lower() for x in MINS] + ["welcome", "break", "wrap-up", "wrap up", "wrapup"]]
    if others:
        fails.append("unexpected item: " + others[0][2])
    if BEFORE:
        a = [r for r in rows if r[2].lower() == BEFORE[0].lower()]
        b = [r for r in rows if r[2].lower() == BEFORE[1].lower()]
        if a and b and a[0][0] > b[0][0]:
            fails.append(BEFORE[0] + " must come before " + BEFORE[1])
    if BRKW and brk and not (BRKW[0] <= brk[0][0] <= BRKW[1]):
        fails.append("the break is outside its allowed window")
    return fails



def main():
    p = Path(TARGET)
    if not p.exists():
        print(f"FAIL: {TARGET} does not exist")
        return 1
    text = p.read_text(encoding="utf-8", errors="replace")
    if not text.strip():
        print(f"FAIL: {TARGET} is empty")
        return 1
    fails = run_checks(RULES, text, globals().get("extra"))
    if fails:
        print("FAIL:")
        for f in fails:
            print(" -", f)
        return 1
    print("OK")
    return 0


if __name__ == "__main__":
    sys.exit(main())

